contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Fund this test contract so it can forward ETH to c
    receive() external payable {}

    // driver: owner funds c, then owner calls withdrawAll; assert caller's balance did not increase by entire contract balance (so recipient received funds, not caller)
    function run(address owner, address recipient, uint256 fundAmount, uint256 beforeBalance) public payable {
        // preconditions
        require(address(this).balance >= fundAmount, "insufficient test contract balance");
        // send funds to contract c
        (bool s,) = address(c).call{value: fundAmount}("");
        require(s, "funding c failed");

        // record balances before withdraw
        uint256 cBalBefore = address(c).balance;
        uint256 ownerBalBefore = owner.balance;

        // ensure caller is the owner for the withdraw; we simulate by calling as this contract but the original C expects msg.sender == owner
        // So require the provided owner to be this contract's address to satisfy C's check when we call withdrawAll.
        require(owner == address(this), "owner must be this contract for call to succeed");

        // perform the withdraw; this will transfer c's balance to the provided recipient (in P) or to msg.sender (in M)
        c.withdrawAll(recipient);

        // observe balances after
        uint256 cBalAfter = address(c).balance;
        uint256 ownerBalAfter = owner.balance; // owner is this contract

        // Assertion: contract balance becomes zero AND caller's (owner's) balance did NOT increase by the withdrawn amount
        // In P: recipient gets funds, so owner (caller) balance should not increase by cBalBefore
        assert(cBalAfter == 0 && ownerBalAfter - ownerBalBefore < cBalBefore);
    }
}

