        // or the test caller supplies owner == address(this). Enforce that here.
        require(owner == address(this));

        c.withdrawAll(owner);

        // Property: after withdrawAll by the owner, c's balance must be zero
        assert(address(c).balance == 0);
    }

    // allow the contract to receive ETH so it can fund deposits
    receive() external payable {}
}

