    // - caller: the address that will call withdrawAll (simulated via call from this contract using low-level call with from not possible in Solidity; instead we rely on the fact that only c.owner() equals some address — so we model by calling withdrawAll from this contract and express the property in terms of c.owner() == address(this) )
    // To satisfy the rule and verifier constraints, we require that the test caller (this contract) is NOT the owner, then calling withdrawAll should NOT drain c's balance on original P. The mutant M removes the require so calling withdrawAll will drain regardless.

    function run(uint256 depositorAmount, address payable recipient) public payable {
        // Preconditions
        require(msg.value >= depositorAmount, "insufficient funds to fund c");
        // fund c so it has a positive balance
        (bool sentToC,) = address(c).call{value: depositorAmount}("");
        require(sentToC, "funding c failed");

        // Ensure this contract is NOT the owner of c; otherwise the property is vacuous
        require(c.owner() != address(this), "test requires this contract not be owner");

