        // via the public getter C.owner() — allowed to call view on c — and comparing owner to caller to state expectation.

        // Make the actual state-changing call as this contract (msg.sender == address(this)). It will succeed iff c.owner == address(this).
        try c.withdrawAll(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Determine whether caller equals owner by reading public owner getter.
        address owner = c.owner();
        // The general rule: call should revert iff caller != owner. Since our actual call was made by this contract,
        // we assert that reverted equals (address(this) != owner). But the test parameter 'caller' is used to require distinction
        // so that the property is stated over inputs: if caller != owner then calls from non-owner must revert. We express this
        // by relating 'caller' to owner: if caller != owner then reverted == true else reverted == (address(this) != owner).
        // Concretely, assert: if caller != owner then reverted must be true; otherwise no constraint beyond value of reverted consistent with owner.

        assert((caller != owner) ? reverted : true);
    }
    receive() external payable { }
}
